import json

levels = {"INFO": 0, "WARN": 0, "ERROR": 0}

with open("app.log") as f:
    for line in f:
        level = line.split()[0]
        if level in levels:
            levels[level] += 1

with open("report.json", "w") as f:
    json.dump(levels, f)

print(levels)

